1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export interface QuoteStep {
7	  op: "quote";
8	  items: {
9	    type: KnownItemType;
10	    material?: string;
11	    enchantment?: number;
12	    cursed?: boolean;
13	  }[];
14	}
15	
16	export type Step = QuoteStep;
17	
18	export interface ScenarioResults {
19	  results: ({ premium: number } | { payout: number; remainingCap: number })[];
20	}
21	
22	const PROCESSING_FEE = 5;
23	const BASE_PREMIUM_BY_TYPE = {
24	  sword: 100,
25	  amulet: 60,
26	  staff: 80,
27	  potion: 40,
28	  rune: 25,
29	  moonstone: 25,
30	} as const satisfies Record<string, number>;
31	
32	export type KnownItemType = keyof typeof BASE_PREMIUM_BY_TYPE;
33	const FIRST_INSURANCE_SURCHARGE = 0.1;
34	
35	// Percentage arithmetic leaves values like 71.00000000000001, which would
36	// otherwise round up to 72. Settle the float noise before rounding.
37	const FLOAT_NOISE_DIGITS = 6;
38	const withoutFloatNoise = (amount: number): number =>
39	  Number(amount.toFixed(FLOAT_NOISE_DIGITS));
40	
41	const roundUpInFavourOfMHPCO = (amount: number): number =>
42	  Math.ceil(withoutFloatNoise(amount));
43	
44	type Item = QuoteStep["items"][number];
45	
46	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
47	
48	const increasedBy = (amount: number, rate: number): number =>
49	  amount * (1 + rate);
50	
51	const BLOCK_SIZE = 3;
52	const BLOCK_BASE_PREMIUM = 60;
53	
54	const groupByType = (items: Item[]): Item[][] => {
55	  const groups = new Map<KnownItemType, Item[]>();
56	  for (const item of items) {
57	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
58	  }
59	  return [...groups.values()];
60	};
61	
62	const sumOfBasePremiums = (items: Item[]): number =>
63	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
64	
65	// Exactly three alike components form a block at a reduced premium; any
66	// other count is priced per item.
67	//
68	// Deliberate simplification: "component" is not yet enforced, so three alike
69	// swords would also get the block. No test covers it and the spec gives no
70	// example — revisit when one does.
71	const groupBasePremiumOf = (group: Item[]): number =>
72	  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(group);
73	
74	const policyBasePremiumOf = (items: Item[]): number =>
75	  groupByType(items).reduce((sum, group) => sum + groupBasePremiumOf(group), 0);
76	
77	const CURSE_SURCHARGE = 0.5;
78	
79	// Item-specific modifiers are charged as a percentage of the affected item's
80	// OWN base premium, unlike policy-wide modifiers which scale the policy base.
81	const shareOfOwnBasePremium = (item: Item, rate: number): number =>
82	  basePremiumOf(item) * rate;
83	
84	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
85	const HIGH_ENCHANTMENT_THRESHOLD = 5;
86	
87	const isHighlyEnchanted = (item: Item): boolean =>
88	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
89	
90	// Both item modifiers can apply at once, and they stack additively: a cursed
91	// item with enchantment 5 pays 50 % + 30 % of its base premium.
92	const totalSurchargeOn = (item: Item): number =>
93	  (item.cursed ? shareOfOwnBasePremium(item, CURSE_SURCHARGE) : 0) +
94	  (isHighlyEnchanted(item)
95	    ? shareOfOwnBasePremium(item, HIGH_ENCHANTMENT_SURCHARGE)
96	    : 0);
97	
98	const itemSurchargesOf = (items: Item[]): number =>
99	  items.reduce((sum, item) => sum + totalSurchargeOn(item), 0);
100	
101	const quotePremium = (step: QuoteStep): number => {
102	  const policyBase = policyBasePremiumOf(step.items);
103	  const policyBaseWithFirstInsurance = increasedBy(
104	    policyBase,
105	    FIRST_INSURANCE_SURCHARGE,
106	  );
107	  return roundUpInFavourOfMHPCO(
108	    policyBaseWithFirstInsurance + itemSurchargesOf(step.items) + PROCESSING_FEE,
109	  );
110	};
111	
112	export const runScenario = (scenario: Scenario): ScenarioResults => ({
113	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
114	});
