const quotePremium = ({ items }: QuoteStep): number => {
  const policyBaseWithFirstInsurance = increasedBy(
    policyBasePremiumOf(items),
    FIRST_INSURANCE_SURCHARGE,
  );
  const itemSurcharges = itemSurchargesOf(items);
  return roundUpInFavourOfMHPCO(
    policyBaseWithFirstInsurance + itemSurcharges + PROCESSING_FEE,
  );
};
